using System;
using System.Collections.Generic;
using System.Linq;
using AICad.Contracts;
using Newtonsoft.Json.Linq;
namespace AICad.Geometry;
public static class DraftingRules {
 public static List<Point2> Wall(Operation op){double dx=op.Points[1].X-op.Points[0].X,dy=op.Points[1].Y-op.Points[0].Y,d=Math.Sqrt(dx*dx+dy*dy);if(d<1)throw new CadException("INVALID_WALL","Tường cần hai đầu tim khác nhau.");double x=-dy/d*op.Height/2,y=dx/d*op.Height/2;return new(){new(op.Points[0].X+x,op.Points[0].Y+y),new(op.Points[1].X+x,op.Points[1].Y+y),new(op.Points[1].X-x,op.Points[1].Y-y),new(op.Points[0].X-x,op.Points[0].Y-y)};}
 public static void Asset(BlockAsset b,TemplateProfile t){if(b.Usage==null)return;var u=b.Usage;if(b.NativeSource==null||!t.Layers.Any(l=>l.Name==u.Layer)||u.WidthBasis!="opening")throw new CadException("INVALID_CATALOG",b.Id);Validation.Finite(u.WidthOffset);Validation.Finite(u.WidthFactor);if(u.WidthFactor<=0||u.WidthFactor>10)throw new CadException("INVALID_CATALOG","Hệ số quy đổi phải lớn hơn 0 và không quá 10.");if(u.Values.Count>40)throw new CadException("INVALID_CATALOG","Quá nhiều tham số.");CheckValues(b,u.Values);foreach(string name in new[]{u.WidthParameter,u.ThicknessParameter}.Where(n=>n!="")){var p=b.NativeSource.DynamicProperties?.SingleOrDefault(p=>p.Name==name&&!p.ReadOnly);if(p==null||p.DefaultValue?.Type!=JTokenType.Float&&p.DefaultValue?.Type!=JTokenType.Integer)throw new CadException("INVALID_CATALOG","Tham số kích thước không hợp lệ: "+name);}}
 public static void CheckValues(BlockAsset b,JObject values){foreach(var v in values.Properties()){var p=b.NativeSource?.DynamicProperties?.SingleOrDefault(p=>p.Name==v.Name&&!p.ReadOnly)??throw new CadException("INVALID_DYNAMIC_PROPERTY",v.Name);if(v.Value.Type!=JTokenType.String&&v.Value.Type!=JTokenType.Integer&&v.Value.Type!=JTokenType.Float&&v.Value.Type!=JTokenType.Boolean)throw new CadException("INVALID_DYNAMIC_VALUE",v.Name);if(p.DefaultValue?.Type==JTokenType.String&&v.Value.Type!=JTokenType.String||p.DefaultValue?.Type==JTokenType.Boolean&&v.Value.Type!=JTokenType.Boolean||(p.DefaultValue?.Type==JTokenType.Integer||p.DefaultValue?.Type==JTokenType.Float)&&v.Value.Type!=JTokenType.Integer&&v.Value.Type!=JTokenType.Float)throw new CadException("INVALID_DYNAMIC_VALUE",v.Name);if(v.Value.Type==JTokenType.Float||v.Value.Type==JTokenType.Integer)Validation.Finite(v.Value.Value<double>());if(p.AllowedValues.Count>0&&!p.AllowedValues.Any(a=>JToken.DeepEquals(a,v.Value)||a.Type!=JTokenType.String&&v.Value.Type!=JTokenType.String&&a.ToString()==v.Value.ToString()))throw new CadException("INVALID_DYNAMIC_VALUE",v.Name);}}
 public static JObject Values(Operation op,BlockAsset b){var v=b.Usage?.Values.DeepClone() as JObject??new();if(op.DynamicJson!=null){var supplied=Json.Read<JObject>(op.DynamicJson);foreach(var p in supplied.Properties())v[p.Name]=p.Value;}var u=b.Usage;if(op.OpeningWidth.HasValue){if(u==null||!u.ConversionConfirmed||u.WidthParameter=="")throw new CadException("WIDTH_BINDING_REQUIRED","Xác nhận quy đổi rộng ô chờ cho block "+b.Id);if(op.OpeningWidth<=0||op.OpeningWidth>20000)throw new CadException("INVALID_OPENING","Rộng ô chờ không hợp lệ.");v[u.WidthParameter]=op.OpeningWidth.Value*u.WidthFactor+u.WidthOffset;}if(op.WallThickness.HasValue){if(u==null||u.ThicknessParameter==""||op.WallThickness!=110&&op.WallThickness!=220)throw new CadException("THICKNESS_BINDING_REQUIRED",b.Id);v[u.ThicknessParameter]=op.WallThickness.Value;}CheckValues(b,v);return v;}
 public static void Operation(Operation op,TemplateProfile t)=>Operation(op,t,false);
 public static void Operation(Operation op,TemplateProfile t,bool draft){if(op.Kind=="draw_wall"&&(op.Height!=110&&op.Height!=220))throw new CadException("INVALID_WALL","Chiều dày tường phải là 220 hoặc 110 mm.");if(op.Kind!="insert_block"){if(op.DynamicJson!=null||op.OpeningWidth!=null||op.WallThickness!=null)throw new CadException("INVALID_DYNAMIC_PROPERTY","Tham số block chỉ áp dụng cho insert_block.");return;}var b=t.Blocks.Single(x=>x.Id==op.AssetId);if(b.Usage!=null&&(op.Layer!=b.Usage.Layer||!draft&&(!b.Usage.Reviewed||b.Usage.WidthParameter!=""&&!b.Usage.ConversionConfirmed)))throw new CadException("CATALOG_REVIEW_REQUIRED","Duyệt loại block và dùng đúng layer: "+b.Id);Values(op,b);}
 public static void Recipe(DraftingRecipe r,TemplateProfile t){if(r.ExteriorWall!=220||r.PartitionWall!=110||r.DoorWidthBasis!="opening")throw new CadException("INVALID_RECIPE","Quy ước: tường 220/110 mm, cửa theo rộng ô chờ xây.");foreach(var role in r.Layers)if(!t.Layers.Any(l=>l.Name==role.Value))throw new CadException("MISSING_LAYER",role.Value);foreach(var id in r.AllowedBlocks){var block=t.Blocks.SingleOrDefault(b=>b.Id==id)??throw new CadException("MISSING_ASSET",id);if(block.Usage?.Reviewed!=true||block.Usage.WidthParameter!=""&&!block.Usage.ConversionConfirmed)throw new CadException("CATALOG_REVIEW_REQUIRED",id);if(r.Layers.TryGetValue(block.Usage.Role,out var required)&&block.Usage.Layer!=required)throw new CadException("CATALOG_LAYER_MISMATCH",id);}if(r.Axes.Count>50)throw new CadException("INVALID_AXES","Tối đa 50 trục.");foreach(var a in r.Axes){if(string.IsNullOrWhiteSpace(a.Name)||a.Name.Length>8||a.Name.Any(char.IsControl)||Validation.Distance(a.Start,a.End)<1)throw new CadException("INVALID_AXES","Nhập tên và hai đầu trục.");Validation.Finite(a.Start.X);Validation.Finite(a.Start.Y);Validation.Finite(a.End.X);Validation.Finite(a.End.Y);}if(r.IncludeAxes&&(!r.AxesConfirmed||r.Axes.Count==0||!r.Layers.ContainsKey("axis")||!r.Layers.ContainsKey("axisHead")))throw new CadException("AXES_CONFIRMATION_REQUIRED","Xác nhận tọa độ, tên trục và layer trục.");}
 public static void Enforce(List<Operation> ops,DraftingRecipe? r,TemplateProfile t)=>Enforce(ops,r,t,false);
 public static void Enforce(List<Operation> ops,DraftingRecipe? r,TemplateProfile t,bool draft){if(r==null)return;Recipe(r,t);foreach(var o in ops){if(o.Kind=="insert_block"&&!r.AllowedBlocks.Contains(o.AssetId)&&(!draft||t.Blocks.Single(b=>b.Id==o.AssetId).Usage==null))throw new CadException("SKILL_ASSET_FORBIDDEN",o.AssetId);if(r.Layers.TryGetValue("wall",out var wall)&&o.Layer==wall&&o.Kind!="draw_wall"&&(draft||o.Kind is not ("draw_line" or "draw_polyline")||t.Id!="ISO_QUANGANH"))throw new CadException("WALL_SPEC_REQUIRED","Tường phải dùng draw_wall với tim tường và chiều dày 220/110.");}}
 public static List<Operation> Axes(DraftingRecipe r){var ops=new List<Operation>();if(!r.IncludeAxes)return ops;foreach(var a in r.Axes){ops.Add(new(){Kind="draw_line",Layer=r.Layers["axis"],Points=new(){new(a.Start.X,a.Start.Y),new(a.End.X,a.End.Y)}});foreach(var p in new[]{a.Start,a.End}){ops.Add(new(){Kind="draw_circle",Layer=r.Layers["axisHead"],Points=new(){new(p.X,p.Y)},Radius=150});ops.Add(new(){Kind="add_text",Layer=r.Layers["axisHead"],Points=new(){new(p.X-45,p.Y-45)},Text=a.Name,Height=100});}}return ops;}
}
